<?php

namespace App\Filament\Resources;

use App\Filament\Resources\AccumulatorBundleResource\Pages;
use App\Models\AccumulatorBundle;
use App\Models\Prediction;
use Filament\Resources\Resource;
use Filament\Tables;
use Filament\Tables\Table;

// Read-only by design: every row here is generated by BundleBuilder on each
// sync, never hand-authored. Delete is the one action kept, for pulling a
// bundle off the site if a selection ever looks wrong before the next sync
// naturally replaces it.
class AccumulatorBundleResource extends Resource
{
    protected static ?string $model = AccumulatorBundle::class;

    protected static ?string $navigationIcon = 'heroicon-o-squares-2x2';

    protected static ?string $navigationLabel = 'Combo Bundles';

    public static function table(Table $table): Table
    {
        return $table
            ->defaultSort('date', 'desc')
            ->columns([
                Tables\Columns\TextColumn::make('type')
                    ->label('Bundle')
                    ->formatStateUsing(fn (AccumulatorBundle $record) => $record->label())
                    ->badge(),
                Tables\Columns\TextColumn::make('date')
                    ->date('D j M Y')
                    ->sortable(),
                Tables\Columns\TextColumn::make('combined_odds')
                    ->label('Combined odds')
                    ->formatStateUsing(fn (?string $state) => $state ? number_format((float) $state, 2) : '—'),
                Tables\Columns\TextColumn::make('legs')
                    ->label('Legs')
                    ->state(fn (AccumulatorBundle $record) => $record->legs
                        ->map(fn (Prediction $p) => "{$p->home} v {$p->away} ({$p->market})")
                        ->implode(' · '))
                    ->wrap(),
            ])
            ->actions([
                Tables\Actions\DeleteAction::make(),
            ]);
    }

    public static function getPages(): array
    {
        return [
            'index' => Pages\ListAccumulatorBundles::route('/'),
        ];
    }

    public static function canCreate(): bool
    {
        return false;
    }
}
